#[derive(Debug, Clone, PartialEq)]
pub struct Command {
    pub aggregate: Option<String>,
    pub entity_id: Option<String>,
    pub name: Option<CommandName>,
    pub role: Option<Actor>,
    pub roles: Vec<Permission>,
    pub goal: Option<Goal>,
    pub emits: Vec<Announcement>,
    pub references: Option<EventName>,
    pub attributes: Vec<Argument>,
    pub givens: Vec<Rule>,
    pub ensures: Vec<Rule>,
    pub needs: Vec<Need>,
    pub mutations: Vec<Change>,
    pub provenance: Option<CommandText>,
    pub idempotent: Option<CommandText>,
    pub from: Option<CommandText>,
    pub position: Option<Position>,
}

impl crate::kernel::Fielded for Command {
    fn field(&self, name: &str) -> Option<crate::kernel::Field<'_>> {
        use crate::kernel::{Field, Value};
        match name {
            "aggregate" => self
                .aggregate
                .as_ref()
                .map(|v| Field::Value(Value::Str(v.clone())))
                .or(Some(Field::Value(Value::Nil))),
            "entity_id" => self
                .entity_id
                .as_ref()
                .map(|v| Field::Value(Value::Str(v.clone())))
                .or(Some(Field::Value(Value::Nil))),
            "name" => self
                .name
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "role" => self
                .role
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "roles" => Some(Field::Value(Value::List(self.roles.len()))),
            "goal" => self
                .goal
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "emits" => Some(Field::Value(Value::List(self.emits.len()))),
            "references" => self
                .references
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "attributes" => Some(Field::Value(Value::List(self.attributes.len()))),
            "givens" => Some(Field::Value(Value::List(self.givens.len()))),
            "ensures" => Some(Field::Value(Value::List(self.ensures.len()))),
            "needs" => Some(Field::Value(Value::List(self.needs.len()))),
            "mutations" => Some(Field::Value(Value::List(self.mutations.len()))),
            "provenance" => self
                .provenance
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "idempotent" => self
                .idempotent
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "from" => self
                .from
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            "position" => self
                .position
                .as_ref()
                .map(|v| Field::Nested(v))
                .or(Some(Field::Value(Value::Nil))),
            _ => None,
        }
    }

    fn items(&self, name: &str) -> Option<Vec<crate::kernel::Field<'_>>> {
        #[allow(unused_imports)]
        use crate::kernel::{Field, Value};
        match name {
            "roles" => Some(self.roles.iter().map(|v| Field::Nested(v)).collect()),
            "emits" => Some(self.emits.iter().map(|v| Field::Nested(v)).collect()),
            "attributes" => Some(self.attributes.iter().map(|v| Field::Nested(v)).collect()),
            "givens" => Some(self.givens.iter().map(|v| Field::Nested(v)).collect()),
            "ensures" => Some(self.ensures.iter().map(|v| Field::Nested(v)).collect()),
            "needs" => Some(self.needs.iter().map(|v| Field::Nested(v)).collect()),
            "mutations" => Some(self.mutations.iter().map(|v| Field::Nested(v)).collect()),
            _ => None,
        }
    }

    fn as_scalar(&self) -> Option<crate::kernel::Value> {
        None
    }
}

