impl Command {
    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
        if !matches!(v, crate::kernel::Json::Object(_)) {
            return Err(crate::kernel::Refusal::TypeMismatch(format!(
                "Command expects an object, got {}",
                v.inspect()
            )));
        }
        Ok(Self {
            aggregate: match v.get("aggregate") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(x.as_str().map(ToString::to_string).ok_or_else(|| {
                    crate::kernel::Refusal::TypeMismatch(format!(
                        "Command.aggregate expects String, got {}",
                        x.describe()
                    ))
                })?),
            },
            entity_id: match v.get("entity_id") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(x.as_str().map(ToString::to_string).ok_or_else(|| {
                    crate::kernel::Refusal::TypeMismatch(format!(
                        "Command.entity_id expects String, got {}",
                        x.describe()
                    ))
                })?),
            },
            name: match v.get("name") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(CommandName::from_json(&x.coerce_single_field("value"))?),
            },
            role: match v.get("role") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(Actor::from_json(&x.coerce_single_field("value"))?),
            },
            roles: match v.get("roles").and_then(crate::kernel::Json::as_array) {
                Some(items) => items
                    .iter()
                    .map(|item| Permission::from_json(&item.coerce_single_field("name")))
                    .collect::<Result<Vec<_>, crate::kernel::Refusal>>()?,
                None => Vec::new(),
            },
            goal: match v.get("goal") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(Goal::from_json(&x.coerce_single_field("value"))?),
            },
            emits: match v.get("emits").and_then(crate::kernel::Json::as_array) {
                Some(items) => items
                    .iter()
                    .map(|item| Announcement::from_json(&item.coerce_single_field("name")))
                    .collect::<Result<Vec<_>, crate::kernel::Refusal>>()?,
                None => Vec::new(),
            },
            references: match v.get("references") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(EventName::from_json(&x.coerce_single_field("value"))?),
            },
            attributes: match v.get("attributes").and_then(crate::kernel::Json::as_array) {
                Some(items) => items
                    .iter()
                    .map(Argument::from_json)
                    .collect::<Result<Vec<_>, crate::kernel::Refusal>>()?,
                None => Vec::new(),
            },
            givens: match v.get("givens").and_then(crate::kernel::Json::as_array) {
                Some(items) => items
                    .iter()
                    .map(Rule::from_json)
                    .collect::<Result<Vec<_>, crate::kernel::Refusal>>()?,
                None => Vec::new(),
            },
            ensures: match v.get("ensures").and_then(crate::kernel::Json::as_array) {
                Some(items) => items
                    .iter()
                    .map(Rule::from_json)
                    .collect::<Result<Vec<_>, crate::kernel::Refusal>>()?,
                None => Vec::new(),
            },
            needs: match v.get("needs").and_then(crate::kernel::Json::as_array) {
                Some(items) => items
                    .iter()
                    .map(|item| Need::from_json(&item.coerce_single_field("fact")))
                    .collect::<Result<Vec<_>, crate::kernel::Refusal>>()?,
                None => Vec::new(),
            },
            mutations: match v.get("mutations").and_then(crate::kernel::Json::as_array) {
                Some(items) => items
                    .iter()
                    .map(Change::from_json)
                    .collect::<Result<Vec<_>, crate::kernel::Refusal>>()?,
                None => Vec::new(),
            },
            provenance: match v.get("provenance") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(CommandText::from_json(&x.coerce_single_field("value"))?),
            },
            idempotent: match v.get("idempotent") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(CommandText::from_json(&x.coerce_single_field("value"))?),
            },
            from: match v.get("from") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(CommandText::from_json(&x.coerce_single_field("value"))?),
            },
            position: match v.get("position") {
                Some(&crate::kernel::Json::Null) | None => None,
                Some(x) => Some(Position::from_json(&x.coerce_single_field("value"))?),
            },
        })
    }
}

