#[derive(Debug, Clone)]
pub struct DeclareArgs {
    pub aggregate: String,
    pub entity_id: Option<String>,
    pub name: CommandName,
    pub role: Option<Actor>,
    pub goal: Option<Goal>,
    pub provenance: Option<CommandText>,
    pub idempotent: Option<CommandText>,
    pub from: Option<CommandText>,
    pub position: Option<Position>,
}

pub fn dispatch_declare(
    repo: &mut impl crate::kernel::Repository<Command>,
    route: Option<&crate::kernel::RoutingEnvelope>,
    owner_id: &str,
    args: DeclareArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Command> {
    args.name.check_invariants()?;
    if let Some(v) = &args.role {
        v.check_invariants()?;
    }
    if let Some(v) = &args.goal {
        v.check_invariants()?;
    }
    if let Some(v) = &args.provenance {
        v.check_invariants()?;
    }
    if let Some(v) = &args.idempotent {
        v.check_invariants()?;
    }
    if let Some(v) = &args.from {
        v.check_invariants()?;
    }
    if let Some(v) = &args.position {
        v.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, COMMAND_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        match route {
            Some(__route) => {
                __route.require_depth(0)?;
                let __hydrate_id: String = format!("{}:{}", owner_id, args.name.value);
                if __route.aggregate() != __hydrate_id.as_str() {
                    return Err(crate::kernel::Refusal::TypeMismatch(format!(
                        "Declare routes to {:?}, but its identity facts name {:?}",
                        __route.aggregate(),
                        __hydrate_id
                    )));
                }
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Command {
                        aggregate: Some(args.aggregate.clone()),
                        entity_id: args.entity_id.clone(),
                        name: Some(args.name.clone()),
                        role: args.role.clone(),
                        roles: vec![],
                        goal: args.goal.clone(),
                        emits: vec![],
                        references: None,
                        attributes: vec![],
                        givens: vec![],
                        ensures: vec![],
                        needs: vec![],
                        mutations: vec![],
                        provenance: args.provenance.clone(),
                        idempotent: args.idempotent.clone(),
                        from: args.from.clone(),
                        position: args.position.clone(),
                    }),
                    state_independent: true,
                }
            }
            None => {
                let __hydrate_id: String = format!("{}:{}", owner_id, args.name.value);
                crate::kernel::Hydrate::Create {
                    id: __hydrate_id,
                    build: Box::new(|| Command {
                        aggregate: Some(args.aggregate.clone()),
                        entity_id: args.entity_id.clone(),
                        name: Some(args.name.clone()),
                        role: args.role.clone(),
                        roles: vec![],
                        goal: args.goal.clone(),
                        emits: vec![],
                        references: None,
                        attributes: vec![],
                        givens: vec![],
                        ensures: vec![],
                        needs: vec![],
                        mutations: vec![],
                        provenance: args.provenance.clone(),
                        idempotent: args.idempotent.clone(),
                        from: args.from.clone(),
                        position: args.position.clone(),
                    }),
                    state_independent: true,
                }
            }
        },
        "Declare",
        "Bluebook::Command",
        "Command",
        "owner_id, name.value",
        &with_references,
        &[],
        None,
        |record| {
            record.aggregate = Some(args.aggregate.clone());
            record.entity_id = args.entity_id.clone();
            record.name = Some(args.name.clone());
            record.role = args.role.clone();
            record.goal = args.goal.clone();
            record.provenance = args.provenance.clone();
            record.idempotent = args.idempotent.clone();
            record.from = args.from.clone();
            record.position = args.position.clone();
            Ok(())
        },
        &[],
        &command_invariants(),
        &["VerbDeclared"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

