pub fn dispatch_change(
    repo: &mut impl crate::kernel::Repository<Command>,
    id: &str,
    args: ChangeArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<Command> {
    args.target.check_invariants()?;
    if ![
        "set",
        "append",
        "increment",
        "decrement",
        "multiply",
        "clamp",
        "remove",
        "delegate",
        "corrects",
    ]
    .contains(&args.op.value.as_str())
    {
        return Err(crate::kernel::Refusal::InvariantViolation(
            crate::kernel::refusal_wording::InvariantViolationAdmitsDeclaredSetArgs {
                name: "op",
                admits: "Vocabulary::MutationOp",
                admitted: &[
                    "set",
                    "append",
                    "increment",
                    "decrement",
                    "multiply",
                    "clamp",
                    "remove",
                    "delegate",
                    "corrects",
                ],
                offered: format!("{:?}", args.op.value).as_str(),
            }
            .render_args(),
        ));
    }
    args.op.check_invariants()?;
    args.field.check_invariants()?;
    args.kind.check_invariants()?;
    args.source.check_invariants()?;
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, COMMAND_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Change",
        "Bluebook::Command",
        "Command",
        "owner_id, name.value",
        &with_references,
        &[
            crate::kernel::GivenSpec {
                description: "a mutation names a target",
                expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(
                    Expr::Lookup("target.value"),
                )))))),
                corrects_event: None,
            },
            crate::kernel::GivenSpec {
                description: "a mutation does something",
                expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(
                    Expr::Lookup("op.value"),
                )))))),
                corrects_event: None,
            },
        ],
        None,
        |record| {
            record.mutations.push(Change {
                target: args.target.value.clone(),
                op: args.op.value.clone(),
                field: args.field.value.clone(),
                kind: args.kind.value.clone(),
                source: args.source.value.clone(),
            });
            Ok(())
        },
        &[],
        &command_invariants(),
        &["ChangeAttached"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

